1	// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
2	// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
3	// Leaflet.markercluster). Prose-only — these are runtime/asset-wiring behaviours,
4	// not repo-state signatures a static check could test. Fingerprinted by an actual
5	// Leaflet reference: a CDN asset (leaflet@ / leaflet.js / leaflet.css) in HTML, or
6	// a Leaflet API call site (L.map( / L.tileLayer( / L.markerClusterGroup() ) in
7	// source. The marker only *suspects* the pack; declaring it is the project's call,
8	// like every pack.
9	const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
10	const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
11	const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;
12	
13	export default {
14	  id: 'leaflet',
15	  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
16	  detect: (ctx) =>
17	    ctx.tracked.some((f) => {
18	      if (!SOURCE.test(f)) return false;
19	      const text = ctx.read(f);
20	      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
21	    }),
22	  prose: 'RULES.md',
23	  rules: [],
24	};
25

1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
3	
4	// Converted from the chrome-extension prose: a `chrome.declarativeContent.SetIcon`
5	// action built with `path` silently leaves the icon unset. The rules are evaluated
6	// by the *browser process*, so the icon must already be raw pixels when the rule is
7	// registered — `imageData` is the only option that survives. Blocking: the failure
8	// is silent (no throw, no console error), so nothing else catches it.
9	//
10	// PARSED, NOT GREPPED (the skill's rule): grep for `path:` would drown in false
11	// alarms, and even `SetIcon` alone is ambiguous. Two scopings kill that:
12	//   1. the `declarativeContent.` qualifier is required — `chrome.action.setIcon({path})`
13	//      is the *correct* use of the (differently-cased) action API and must stay quiet;
14	//   2. only the SetIcon argument's OWN depth-1 keys are read, so a `path` nested
15	//      deeper, or belonging to some neighbouring call, is not this rule's business.
16	// Comments are stripped first, so prose describing the trap never fires it.
17	
18	const SOURCE = /\.(?:mjs|cjs|js|jsx|ts|tsx)$/;
19	const CALL = /\bdeclarativeContent\s*\.\s*SetIcon\s*\(\s*\{/g;
20	
21	// Advance past a string/template literal that opens at `i`, honoring backslash
22	// escapes; returns the index of its closing quote. Shared by both passes so a
23	// brace or colon inside "a{b:c}" can never be read as syntax.
24	function endOfString(src, i) {
25	  const quote = src[i];
26	  for (i += 1; i < src.length; i++) {
27	    if (src[i] === '\\') { i += 1; continue; }
28	    if (src[i] === quote) return i;
29	  }
30	  return src.length;
31	}
32	
33	// The balanced object literal beginning at the `{` at index `open`, or null when
34	// the source is unbalanced (a half-written file — say nothing rather than guess).
35	function objectLiteral(src, open) {
36	  let depth = 0;
37	  for (let i = open; i < src.length; i++) {
38	    const c = src[i];
39	    if (c === '"' || c === "'" || c === '`') { i = endOfString(src, i); continue; }
40	    if (c === '{' || c === '[' || c === '(') depth += 1;
41	    else if (c === '}' || c === ']' || c === ')') {
42	      depth -= 1;
43	      if (depth === 0) return src.slice(open, i + 1);
44	    }
45	  }
46	  return null;
47	}
48	
49	// The property names written at the object's own top level — `{ path: … }` and
50	// `{ 'path': … }` count, anything inside a nested object/array/call does not.
51	function topLevelKeys(obj) {
52	  const keys = [];
53	  let depth = 0;
54	  let token = '';
55	  for (let i = 0; i < obj.length; i++) {
56	    const c = obj[i];
57	    if (c === '"' || c === "'" || c === '`') {
58	      const end = endOfString(obj, i);
59	      if (depth === 1) token = obj.slice(i + 1, end);
60	      i = end;
61	      continue;
62	    }
63	    if (c === '{' || c === '[' || c === '(') { depth += 1; token = ''; continue; }
64	    if (c === '}' || c === ']' || c === ')') { depth -= 1; token = ''; continue; }
65	    if (depth !== 1) continue;
66	    if (c === ':') { if (token.trim()) keys.push(token.trim()); token = ''; continue; }
67	    if (c === ',') { token = ''; continue; }
68	    token += c;
69	  }
70	  return keys;
71	}
72	
73	const rule = {
74	  id: 'declarative-content-set-icon',
75	  severity: 'blocking',
76	  description: 'A chrome.declarativeContent.SetIcon action supplies imageData, never path',
77	  doc: 'packs/chrome-extension/RULES.md',
78	  why: 'declarativeContent rules are evaluated by the browser process, so the icon must already be raw pixels at registration time — the documented path option can silently leave the icon unset, with no throw and no console error to notice',
79	
80	  run(ctx) {
81	    const out = [];
82	    for (const file of ctx.files) {
83	      if (!SOURCE.test(file)) continue;
84	      const raw = ctx.read(file);
85	      if (raw === null || !raw.includes('declarativeContent')) continue;
86	      const src = stripComments(raw);
87	      CALL.lastIndex = 0;
88	      for (let m = CALL.exec(src); m; m = CALL.exec(src)) {
89	        const obj = objectLiteral(src, m.index + m[0].length - 1);
90	        if (obj === null || !topLevelKeys(obj).includes('path')) continue;
91	        out.push(finding(rule, {
92	          file,
93	          line: src.slice(0, m.index).split('\n').length,
94	          what: 'builds a declarativeContent.SetIcon action from a path',
95	          fix: "pass imageData instead — a service worker has no DOM, so decode the packaged icon yourself: fetch(chrome.runtime.getURL(icon)) → blob → createImageBitmap → OffscreenCanvas.drawImage → getImageData",
96	        }));
97	      }
98	    }
99	    return out;
100	  },
101	};
102	
103	export default rule;
