1	// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
2	// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
3	// Leaflet.markercluster). Most are runtime behaviours with no repo-state
4	// signature and stay prose; the CDN wiring of the assets themselves is written
5	// into the HTML, so it converts. Fingerprinted by an actual Leaflet reference: a
6	// CDN asset (leaflet@ / leaflet.js / leaflet.css) in HTML, or a Leaflet API call
7	// site (L.map( / L.tileLayer( / L.markerClusterGroup() ) in source. The marker
8	// only *suspects* the pack; declaring it is the project's call, like every pack.
9	import assetIntegrity from './asset-integrity.mjs';
10	
11	const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
12	const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
13	const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;
14	
15	export default {
16	  id: 'leaflet',
17	  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
18	  detect: (ctx) =>
19	    ctx.tracked.some((f) => {
20	      if (!SOURCE.test(f)) return false;
21	      const text = ctx.read(f);
22	      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
23	    }),
24	  prose: 'RULES.md',
25	  rules: [],
26	};
